/** An RGB color with eight bits per channel. */
export interface Rgb {
  r: number;
  g: number;
  b: number;
}

export type Color =
  | { kind: "default" }
  | { kind: "indexed"; value: number }
  | { kind: "rgb"; value: Rgb };
export type Underline = "none" | "single" | "double" | "curly" | "dotted" | "dashed";
export type Blink = "none" | "slow" | "rapid";
export type Frame = "none" | "framed" | "encircled";
export type Ideogram =
  | "none"
  | "underline"
  | "double_underline"
  | "overline"
  | "double_overline"
  | "stress";

export interface Attributes {
  bold: boolean;
  dim: boolean;
  italic: boolean;
  underline: Underline;
  blink: Blink;
  reverse: boolean;
  hidden: boolean;
  strikethrough: boolean;
  frame: Frame;
  overline: boolean;
  ideogram: Ideogram;
}

export interface Style {
  foreground: Color;
  background: Color;
  underline_color: Color;
  attributes: Attributes;
}

export type CellWidth = "single" | "wide" | "continuation";
export interface Cell {
  symbol: string;
  width: CellWidth;
  style: Style;
}
export type CursorShape = "block" | "bar" | "underline";
export interface Cursor {
  x: number;
  y: number;
  shape: CursorShape;
  visible: boolean;
}

/** Exact serde wire shape validated by tuishot-core::Grid. */
export interface Grid {
  columns: number;
  rows: number;
  cells: Cell[];
  cursor: Cursor | null;
}

export type Scale = 1 | 2 | 3 | 4;
export type Theme = "dark" | "light";
export type WindowChrome = "none" | "macos";
export interface RenderOptions {
  /** Integer raster scale. Defaults to 1. */
  scale?: Scale;
  /** Built-in deterministic palette. Defaults to dark. */
  theme?: Theme;
  /** Window decoration. Defaults to none. */
  chrome?: WindowChrome;
}
export interface AnsiDimensions {
  /** Terminal columns. Combined area is limited to 1,000,000 cells. */
  cols: number;
  /** Terminal rows. */
  rows: number;
}
export type RenderAnsiOptions = RenderOptions & AnsiDimensions;
export interface RenderResult {
  png: Uint8Array;
  svg: string;
  /** Full rectangle, including spaces and final blank rows. */
  txt: string;
  json: Grid;
}

export type InitInput =
  | WebAssembly.Module
  | BufferSource
  | Response
  | Promise<Response>;

/**
 * Initialize the one shared wasm module. With no argument, the selected entry
 * loads it through fs (Node), fetch (browser), Bun.file, or Deno.readFile.
 * Calls are idempotent and concurrent calls share one promise.
 */
export function init(input?: InitInput | Promise<InitInput>): Promise<void>;

/** Returns the Rust package version. Call after init(). */
export function version(): string;

/** Synchronous renderer. Construct only after `await init()`. */
export class Renderer {
  constructor(options?: RenderOptions);
  free(): void;
  normalizeGrid(grid: Grid): Grid;
  gridToPng(grid: Grid): Uint8Array;
  gridToSvg(grid: Grid): string;
  gridToText(grid: Grid): string;
  /** Stable compact JSON generated by Rust serde field order. */
  gridToJson(grid: Grid): string;
  ansiToGrid(ansi: string, options: AnsiDimensions): Grid;
  ansiToPng(ansi: string, options: AnsiDimensions): Uint8Array;
  ansiToSvg(ansi: string, options: AnsiDimensions): string;
  ansiToText(ansi: string, options: AnsiDimensions): string;
  ansiToJson(ansi: string, options: AnsiDimensions): string;
  renderGrid(grid: Grid): RenderResult;
  renderAnsi(ansi: string, options: AnsiDimensions): RenderResult;
}

/** Async one-shot helpers initialize the selected runtime loader automatically. */
export function renderGrid(grid: Grid, options?: RenderOptions): Promise<RenderResult>;
export function renderAnsi(ansi: string, options: RenderAnsiOptions): Promise<RenderResult>;
export function gridToPng(grid: Grid, options?: RenderOptions): Promise<Uint8Array>;
export function gridToSvg(grid: Grid, options?: RenderOptions): Promise<string>;
export function gridToText(grid: Grid, options?: RenderOptions): Promise<string>;
export function gridToJson(grid: Grid, options?: RenderOptions): Promise<string>;
export function ansiToGrid(ansi: string, options: RenderAnsiOptions): Promise<Grid>;
export function ansiToPng(ansi: string, options: RenderAnsiOptions): Promise<Uint8Array>;
export function ansiToSvg(ansi: string, options: RenderAnsiOptions): Promise<string>;
export function ansiToText(ansi: string, options: RenderAnsiOptions): Promise<string>;
export function ansiToJson(ansi: string, options: RenderAnsiOptions): Promise<string>;

declare const api: {
  init: typeof init;
  Renderer: typeof Renderer;
  version: typeof version;
  renderGrid: typeof renderGrid;
  renderAnsi: typeof renderAnsi;
  gridToPng: typeof gridToPng;
  gridToSvg: typeof gridToSvg;
  gridToText: typeof gridToText;
  gridToJson: typeof gridToJson;
  ansiToGrid: typeof ansiToGrid;
  ansiToPng: typeof ansiToPng;
  ansiToSvg: typeof ansiToSvg;
  ansiToText: typeof ansiToText;
  ansiToJson: typeof ansiToJson;
};
export default api;
